let client = reqwest::Client::new();
let res = client.post("http://localhost:8000/api/pull")
    .json(&serde_json::json!({ "name": "qwen:0.5b", "stream": false }))
    .send()
    .await?;
println!("{:#?}", res.json::<serde_json::Value>().await?);

